  const assignments = settlement2.practiceSlots.map((slot, slotIndex) => ({ slotIndex, practiceId: slot?.practiceId ?? null, tokens: [], effectiveWorkers: 0 }));
  const defs = assignments.map((a) => getDetailedPracticeDef(state, a.practiceId));
