// src/model/moon.js
function clampInt(v, fallback) {
  const n = Math.floor(v);
  return Number.isFinite(n) ? n : fallback;
}
function getMoonPhase01AtSecond(tSec) {
  return getMoonPhaseStateAtSecond(tSec).phase01;
}
function isMoonWaxingAtSecond(tSec) {
  return getMoonPhaseStateAtSecond(tSec).isWaxing;
}
function getMoonPhaseStateAtSecond(tSec) {
  const cycleSec = Math.max(1, clampInt(MOON_CYCLE_SEC, 30));
  const offsetSec = clampInt(
    MOON_PHASE_OFFSET_SEC,
    Math.floor(cycleSec / 2)
  );
  const t = Math.max(0, clampInt(tSec, 0));
  const phaseSec = (t + offsetSec) % cycleSec;
  const half = cycleSec / 2;
  const ratio = phaseSec <= half ? phaseSec / Math.max(1, half) : (cycleSec - phaseSec) / Math.max(1, half);
  const phase01 = Math.max(0, Math.min(1, ratio));
  return {
    phase01,
    isWaxing: phaseSec <= half,
    phaseSec,
    cycleSec
  };
}
function getActionPointCapAtSecond(tSec) {
  const minCap = Math.max(0, clampInt(AP_CAP_MIN, 0));
  const maxCap = Math.max(minCap, clampInt(AP_CAP_MAX, 100));
  const phase = getMoonPhase01AtSecond(tSec);
  return Math.round(minCap + phase * (maxCap - minCap));
}

// src/defs/tooltip-ui-utils.js
function asArray(value) {
  return Array.isArray(value) ? value : [];
}
function ensureTooltipCardUi(registry, { getTitle = null, getLines = null, getKeywords = null } = {}) {
  if (!registry || typeof registry !== "object") return registry;
  for (const def of Object.values(registry)) {
    if (!def || typeof def !== "object") continue;
    if (!def.ui || typeof def.ui !== "object") def.ui = {};
    if (!def.ui.tooltipCard || typeof def.ui.tooltipCard !== "object") {
      const title5 = typeof getTitle === "function" ? getTitle(def) : def.ui.title || def.ui.name || def.name || def.id || "";
      const lines = typeof getLines === "function" ? asArray(getLines(def)).filter(Boolean) : asArray(def.ui.lines).length > 0 ? asArray(def.ui.lines).filter(Boolean) : def.ui.description ? [def.ui.description] : [];
      def.ui.tooltipCard = {
        title: title5,
        lines
      };
    }
    if (!Array.isArray(def.ui.keywords)) {
      def.ui.keywords = typeof getKeywords === "function" ? asArray(getKeywords(def)).filter(Boolean) : [];
    }
  }
  return registry;
}

