    cost: state.rulesetId ? quotePrestige(state.civilization.prestige, getAdjustedVassalPrestigeCost(vassal, option.prestigeCost ?? 0)).prestigeCost : getAdjustedVassalPrestigeCost(vassal, option.prestigeCost ?? 0),
    phases: state.gameConfig.lifeMapGenerator.design.enabled ? getVassalActionPhaseCost(vassal, option.phaseCost, { nodeState }) : option.phaseCost,
