  const settlement2 = site.detailedState, beneficiary = slot.allegiance;
  if (def.populationCondition === "housed" && getPopulationSummary(state, site.regionId).total > getPopulationSummary(state, site.regionId).housingCapacity) return { ok: false, reason: "Housing required for all residents" };
  if (def.populationCondition === "relief" && !(settlement2.mealRelief?.tSec === state.tSec && settlement2.mealRelief.faction === beneficiary && settlement2.mealRelief.amount > 0 && settlement2.mealRelief.fullyFed)) return { ok: false, reason: "Requires actual allied meal relief after local shortage" };
