// src/model/detailed-settlements/view-model.js
function getDetailedCivilizationSummary(state) {
  const sites2 = getDetailedSettlementSites(state, { playerOnly: true });
  const byClass = Object.fromEntries(
    POPULATION_CLASS_ORDER.map((classId) => [
      classId,
      {
        children: 0,
        adults: 0,
        elders: 0,
        total: 0,
        assignedWorkers: 0,
        freePopulation: 0
      }
    ])
  );
  const population = {
    children: 0,
    adults: 0,
    elders: 0,
    total: 0,
    mealDemand: 0,
    housingCapacity: 0,
    byClass
  };
  let storedFood = 0;
  let looseFood = 0;
  let storedFoodCapacity = 0;
  let overHousingSiteCount = 0;
  for (const site of sites2) {
    const regionId = site.regionId;
    const localPopulation = getPopulationSummary(state, regionId);
    const workerAssignments = assignDetailedSettlementWorkers(state, regionId);
    const assignedByClass = Object.fromEntries(
      POPULATION_CLASS_ORDER.map((classId) => [classId, 0])
    );
    for (const assignment of workerAssignments) {
      for (const token of assignment.tokens ?? []) {
        if (!Object.prototype.hasOwnProperty.call(assignedByClass, token?.classId)) {
          continue;
        }
        assignedByClass[token.classId] += 1;
      }
    }
    population.children += localPopulation.children;
    population.adults += localPopulation.adults;
    population.elders += localPopulation.elders;
    population.total += localPopulation.total;
    population.mealDemand += localPopulation.mealDemand;
    population.housingCapacity += localPopulation.housingCapacity;
    if (localPopulation.total > localPopulation.housingCapacity) {
      overHousingSiteCount += 1;
    }
    for (const classId of POPULATION_CLASS_ORDER) {
      const source = localPopulation.byClass[classId] ?? {};
      const target = byClass[classId];
      target.children += source.children ?? 0;
      target.adults += source.adults ?? 0;
      target.elders += source.elders ?? 0;
      target.total += source.total ?? 0;
      target.assignedWorkers += assignedByClass[classId] ?? 0;
      target.freePopulation += Math.max(
        0,
        (source.adults ?? 0) + (source.elders ?? 0) - (assignedByClass[classId] ?? 0)
      );
    }
    storedFood += stockTotal(state, site.detailedState, "Edible");
    looseFood += 0;
    storedFoodCapacity += getStoredFoodCapacity(state, regionId);
  }
  storedFood = roundFood(storedFood);
  looseFood = roundFood(looseFood);
  storedFoodCapacity = roundFood(storedFoodCapacity);
  return {
    settlementCount: sites2.length,
    regionIds: sites2.map((site) => site.regionId),
    specialists: Object.fromEntries(["scholar", "warrior"].map((c) => [c, sites2.reduce((n, s) => n + specialistCount(s.detailedState, c), 0)])),
    population,
    food: {
      stored: storedFood,
      loose: looseFood,
      total: roundFood(storedFood + looseFood),
      storedCapacity: storedFoodCapacity
    },
    research: roundFood(state?.civilization?.research?.total ?? 0),
    overHousingSiteCount,
    chaos: {
      chaosPower: Math.max(0, Number(state?.civilization?.chaos?.chaosPower) || 0),
      resistance: getChaosResistance(state),
      expansionProgress: state?.civilization?.chaos?.monsterPressure ?? 0,
      expansionThreshold: getGameSetting(state, "monsterExpansionThreshold"),
      progressPerMoon: getMonsterPressureRate(state),
      monsterCount: Math.max(0, Math.floor(state?.civilization?.chaos?.monsterCount ?? 0)),
      lastReckoning: clone(state?.civilization?.chaos?.lastMoonIncome ?? null)
    },
    green: getGreenAscendancySummary(state)
  };
}
function getDetailedSettlementViewModel(state, regionId) {
  const site = getDetailedSettlementSite(state, regionId);
  if (!site) return null;
  const region2 = getRegionState(state, regionId);
  const settlement2 = site.detailedState;
  const population = getPopulationSummary(state, regionId);
  const workers = assignDetailedSettlementWorkers(state, regionId);
  const availableWorkerCount = POPULATION_CLASS_ORDER.reduce(
    (total, classId) => {
      const cohort = population.byClass[classId] ?? {};
      return total + Math.floor(
        (Math.max(0, cohort.adults ?? 0) + Math.max(0, cohort.elders ?? 0)) / Math.max(1, getGameSetting(state, "populationPerToken"))
      );
    },
    0
  );
  const activeWorkerCount = workers.reduce(
    (total, assignment) => total + (assignment.tokens?.length ?? 0),
    0
  );
  return {
    regionId,
    siteId: site.id,
    control: state.rulesetId ? controlSummary(state, regionId) : null,
    prestigePopulationPerPoint: TERRITORIAL_PRESTIGE_POPULATION_PER_POINT,
    prestigePerNode: getRegionPrestigePerNode(state, regionId),
    civilizationPrestige: state.rulesetId ? state.civilization.prestige : null,
    supportTargets: state.rulesetId ? garrisonSupportTargets(state, regionId) : [],
    name: site.name,
    neutral: !!site.neutral,
    marketStocks: clone(site.neutral?.stocks ?? []),
    marketCurrency: site.neutral?.currencyStock ?? 0,
    lastDefense: clone(settlement2.lastDefense ?? null),
    martialForce: state.rulesetId ? militarySummary(state, regionId).defense : getMartialForce(state),
    martialSupport: state.rulesetId ? militarySummary(state, regionId).force : getMartialSupport(state, regionId),
    defensiveSupport: state.rulesetId ? militarySummary(state, regionId).defense : getMartialSupport(state, regionId, true),
    storedFood: stockTotal(state, settlement2, "Edible"),
    looseFood: 0,
    currency: stockTotal(state, settlement2, "Currency"),
    currencySpentThisMoon: roundFood(state.civilization.currentMoonTurn?.regions?.[regionId]?.currencySpent ?? 0),
    currencySpentLastMoon: roundFood(settlement2.lastMoonResult?.currencySpent ?? 0),
    storedFoodCapacity: getStoredFoodCapacity(state, regionId),
    specialists: { scholar: specialistCount(settlement2, "scholar"), warrior: specialistCount(settlement2, "warrior") },
    population,
    pressure: getSettlementPressureSummary(state, regionId),
    workerPool: {
      availableWorkerCount,
      activeWorkerCount,
      unusedWorkerCount: Math.max(
        0,
        availableWorkerCount - activeWorkerCount
      )
    },
    practices: settlement2.practiceSlots.map((slot, index) => ({
      ...slot,
      label: slot ? getDetailedPracticeDef(state, slot.practiceId)?.label ?? slot.practiceId : null,
      tags: slot ? getPracticeTags(state, slot.practiceId, workers[index]) : [],
      face: slot ? getGamepieceFace(state, "practice", slot.practiceId, slot.tier, { evaluation: buildDetailedPracticeEvaluation(state, site, workers[index]), workers: workers[index], slot, settlement: settlement2, activationTrace: settlement2.practiceActivationTrace ?? [] }) : null,
      workers: workers[index],
      evaluation: slot ? buildDetailedPracticeEvaluation(state, site, workers[index]) : null
    })),
    structures: settlement2.structureSlots.map((slot) => slot ? { ...slot, face: getGamepieceFace(state, "structure", slot.structureId, getDetailedStructureDef(state, slot.structureId)?.minimumQuality, { slot, settlement: settlement2 }), label: getDetailedStructureDef(state, slot.structureId)?.label ?? slot.structureId, tags: getDetailedStructureDef(state, slot.structureId)?.tags ?? [] } : null),
    structureCapacity: region2?.structureCapacity ?? 0,
    usedStructureCapacity: occupiedCells(settlement2.structureSlots).filter(Boolean).length,
    elderOrder: getElderOrderSummary(state, regionId),
    lastMeal: settlement2.lastMeal,
    currentMoonResult: state.civilization.currentMoonTurn?.regions?.[regionId] ?? null,
    lastMoonResult: settlement2.lastMoonResult,
    research: roundFood(state.civilization.research?.total ?? 0),
    localTags: getLocalDistinctPieceTags(state, regionId),
    retiredVassals: (state.civilization.retiredVassals ?? []).filter((entry) => entry.retirementRegionId === regionId),
    activationTrace: settlement2.practiceActivationTrace ?? []
  };
}

// src/model/init.js
function cloneSerializable3(value) {
  if (value == null) return null;
  return JSON.parse(JSON.stringify(value));
}
function getSetupSkillProgressionDefs(setup) {
  const raw = setup?.skillProgressionDefs;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  return cloneSerializable3(raw);
}
function recomputeInitialActionPoints(state) {
  if (!state || typeof state !== "object") return;
  const tSec = Number.isFinite(state.tSec) ? Math.floor(state.tSec) : 0;
  if (state.apCapOverride?.enabled === true) {
    const overrideCap = Number.isFinite(state.apCapOverride.cap) ? Math.max(0, Math.floor(state.apCapOverride.cap)) : Math.max(0, Math.floor(state.actionPointCap ?? 0));
    const overridePoints = Number.isFinite(state.apCapOverride.points) ? Math.floor(state.apCapOverride.points) : Math.floor(state.actionPoints ?? 0);
    state.actionPointCap = overrideCap;
    state.actionPoints = Math.min(overrideCap, Math.max(0, overridePoints));
    return;
  }
  const baseCap = getActionPointCapAtSecond(tSec);
  const skillCapBonus = Math.floor(getGlobalSkillModifier(state, "apCapBonus", 0));
  state.actionPointCap = Math.max(0, baseCap + skillCapBonus);
  state.actionPoints = Math.min(
    state.actionPointCap,
    Math.max(0, Math.floor(state.actionPoints ?? 0))
  );
}
function createInitialState(scenario = "devPlaytesting01", seed = null) {
  const setup = typeof scenario === "string" ? setupDefs[scenario] : scenario;
  if (!setup) {
    throw new Error(
      typeof scenario === "string" ? `Unknown setupId: ${scenario}` : "Invalid scenario object"
    );
  }
  const state = createEmptyState(
    seed ?? setup.rngSeed ?? 123456789,
    setup?.worldDefinitionId ?? "riverBasin01",
    setup?.worldDraft ?? null
  );
  state.gameConfig = canonicalizeGameConfig(setup?.gameConfig);
  state.seasonDurationSec = getGameSetting(state, "seasonDurationSec");
  state.civilization = {
    capitalRegionId: typeof setup?.civilization?.capitalRegionId === "string" ? setup.civilization.capitalRegionId : state.civilization.capitalRegionId,
    capitalSiteId: typeof setup?.civilization?.capitalSiteId === "string" ? setup.civilization.capitalSiteId : state.civilization.capitalSiteId
  };
  state.variantFlags = normalizeVariantFlags(setup?.variantFlags);
  state.skillProgressionDefs = getSetupSkillProgressionDefs(setup);
  state.phase = "simulation";
  state.turn = 0;
  state.currentSeasonIndex = 0;
  state.year = 1;
  state.seasonTimeRemaining = 0;
  state.paused = false;
  initializeDetailedSettlementCivilization(state);
  recomputeInitialActionPoints(state);
  return state;
}

