// src/model/map-lab-draft.js
var MAP_LAB_DRAFT_SCHEMA_VERSION = 8;
var clone7 = (value) => JSON.parse(JSON.stringify(value));
var definitionFor = getWorldDefinitionById;
function normalizeDetailedState(raw, capacity, regionId = null) {
  const fallback = createInitialDetailedSettlementData(regionId);
  const state = raw && typeof raw === "object" ? clone7(raw) : fallback;
  state.populationByClass = state.populationByClass ?? fallback.populationByClass;
  state.practiceSlots = Array.isArray(state.practiceSlots) ? state.practiceSlots.slice(0, DETAILED_PRACTICE_SLOT_COUNT) : [];
  while (state.practiceSlots.length < DETAILED_PRACTICE_SLOT_COUNT) state.practiceSlots.push(null);
  state.practiceSlots = state.practiceSlots.map((slot) => slot && slot.tier == null ? { ...slot, tier: "bronze" } : slot);
  state.structureSlots = normalizeStructureLayout(state.structureSlots, capacity, (id) => settlementStructureDefs[id], regionId);
  state.elderOrder = state.elderOrder ?? fallback.elderOrder;
  state.lastMeal = null;
  state.lastMoonResult = null;
  return state;
}
function canonicalizeMapLabDraft(value) {
  const draft = clone7(value);
  const definition = definitionFor(draft?.worldDefinitionId);
  if (!definition) return draft;
  const regionById = new Map((draft.regions ?? []).map((entry) => [entry?.id, entry]));
  draft.schemaVersion = MAP_LAB_DRAFT_SCHEMA_VERSION;
  draft.regions = definition.regions.map((regionDef) => {
    const source = regionById.get(regionDef.id) ?? regionDef.initialState;
    const structureCapacity = Number.isInteger(source.structureCapacity) ? source.structureCapacity : regionDef.initialState.structureCapacity;
    const detailedSettlementEnabled = source.detailedSettlementEnabled === true;
    return {
      id: regionDef.id,
      colour: source.colour,
      controller: source.controller,
      structureCapacity,
      randomizeStructureCapacity: source.randomizeStructureCapacity === true,
      detailedSettlementEnabled,
      detailedState: detailedSettlementEnabled ? normalizeDetailedState(source.detailedState, structureCapacity, regionDef.id) : null
    };
  });
  draft.connections = canonicalizeWorldConnections(draft.connections ?? [], definition);
  return draft;
}
function createAuthoredMapLabDraft(worldDefinitionId = "riverBasin01") {
  const definition = definitionFor(worldDefinitionId);
  if (!definition) throw new Error(`Unknown world definition: ${worldDefinitionId}`);
  const siteByRegion = new Map(definition.sites.map((site) => [site.regionId, site]));
  return canonicalizeMapLabDraft({
    schemaVersion: MAP_LAB_DRAFT_SCHEMA_VERSION,
    worldDefinitionId,
    regions: definition.regions.map((entry) => ({
      id: entry.id,
      ...clone7(entry.initialState),
      detailedState: siteByRegion.has(entry.id) ? createInitialDetailedSettlementData(entry.id) : null
    })),
    connections: clone7(definition.connections)
  });
}

